import { app } from 'electron'
import { createHash } from 'crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs'
import { join } from 'path'

const MAX_RECENTS = 16

export interface RecentFile {
  path: string
  name: string
  lastOpened: number
  pageCount?: number
  /** Small JPEG data URL of the first page, generated by the renderer. */
  thumbnail?: string
}

export interface ViewState {
  page: number
  zoom: number
}

function dataRoot(): string {
  const root = join(app.getPath('userData'), 'inkwell-data')
  if (!existsSync(root)) mkdirSync(root, { recursive: true })
  return root
}

function idFor(pdfPath: string): string {
  return createHash('sha256').update(pdfPath).digest('hex').slice(0, 16)
}

function ensureDir(sub: string): string {
  const dir = join(dataRoot(), sub)
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true })
  return dir
}

function readJson<T>(file: string): T | null {
  if (!existsSync(file)) return null
  try {
    return JSON.parse(readFileSync(file, 'utf-8')) as T
  } catch {
    return null
  }
}

export function loadAnnotations(pdfPath: string): unknown | null {
  return readJson(join(ensureDir('annotations'), `${idFor(pdfPath)}.json`))
}

export function saveAnnotations(pdfPath: string, data: unknown): void {
  const file = join(ensureDir('annotations'), `${idFor(pdfPath)}.json`)
  writeFileSync(file, JSON.stringify(data), 'utf-8')
}

export function loadNotes(pdfPath: string): string | null {
  const file = join(ensureDir('notes'), `${idFor(pdfPath)}.md`)
  if (!existsSync(file)) return null
  return readFileSync(file, 'utf-8')
}

export function saveNotes(pdfPath: string, markdown: string): void {
  const file = join(ensureDir('notes'), `${idFor(pdfPath)}.md`)
  writeFileSync(file, markdown, 'utf-8')
}

export function loadViewState(pdfPath: string): ViewState | null {
  return readJson(join(ensureDir('views'), `${idFor(pdfPath)}.json`))
}

export function saveViewState(pdfPath: string, state: ViewState): void {
  const file = join(ensureDir('views'), `${idFor(pdfPath)}.json`)
  writeFileSync(file, JSON.stringify(state), 'utf-8')
}

function recentsFile(): string {
  return join(dataRoot(), 'recents.json')
}

export function listRecents(): RecentFile[] {
  const recents = readJson<RecentFile[]>(recentsFile()) ?? []
  // Drop files that have been moved or deleted since they were last opened
  return recents.filter((r) => existsSync(r.path))
}

function writeRecents(recents: RecentFile[]): void {
  writeFileSync(recentsFile(), JSON.stringify(recents.slice(0, MAX_RECENTS)), 'utf-8')
}

export function touchRecent(entry: Omit<RecentFile, 'lastOpened'>): void {
  const recents = listRecents()
  const existing = recents.find((r) => r.path === entry.path)
  const merged: RecentFile = { ...existing, ...entry, lastOpened: Date.now() }
  writeRecents([merged, ...recents.filter((r) => r.path !== entry.path)])
}

export function updateRecent(pdfPath: string, patch: Partial<RecentFile>): void {
  const recents = listRecents()
  const index = recents.findIndex((r) => r.path === pdfPath)
  if (index === -1) return
  recents[index] = { ...recents[index], ...patch, path: pdfPath }
  writeRecents(recents)
}

export function removeRecent(pdfPath: string): void {
  writeRecents(listRecents().filter((r) => r.path !== pdfPath))
}
